package com.renthub.booking; import com.renthub.auth.AuthService; import com.renthub.user.User; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/bookings") @CrossOrigin(origins="http://localhost:5173") public class BookingController{private final BookingRepository repo;private final BookingService service;private final AuthService auth;public BookingController(BookingRepository r,BookingService s,AuthService a){repo=r;service=s;auth=a;} @GetMapping("/mine") public List<Booking> mine(@RequestHeader(value="Authorization",required=false)String h){return repo.findByUserIdOrderByCreatedAtDesc(auth.require(h).getId());} @GetMapping public List<Booking> all(@RequestHeader(value="Authorization",required=false)String h){User u=auth.require(h);auth.requireRole(u,"ADMIN");return repo.findAll();} @PostMapping public Booking create(@RequestHeader(value="Authorization",required=false)String h,@Valid @RequestBody BookingRequest q){return service.create(auth.require(h).getId(),q);} @PatchMapping("/{id}/cancel") public Booking cancel(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id){User u=auth.require(h);return service.cancel(u.getId(),id,"ADMIN".equalsIgnoreCase(u.getRole()));}}
